import type { ReactNode, Ref } from 'react'
import { Switch as BaseSwitch } from '@base-ui/react/switch'
import { cn } from '@/lib/utils'
import { ChoiceField, choiceStyles, type ValidationState } from './ChoiceField'
import styles from './Switch.module.css'

export interface SwitchProps {
  ref?: Ref<HTMLElement>
  /** Controlled state. */
  checked?: boolean
  /** Uncontrolled starting state (the spec's `defaultValue`). */
  defaultChecked?: boolean
  /** The spec's `onChange`. Base UI's event details are dropped. */
  onCheckedChange?: (checked: boolean) => void
  label?: ReactNode
  helperText?: ReactNode
  name?: string
  /** Submitted when on; "on" by default, like a checkbox. */
  value?: string
  size?: 'sm' | 'md' | 'lg'
  /** Colour of the on state. */
  variant?: 'primary' | 'accent' | 'destructive'
  disabled?: boolean
  required?: boolean
  readOnly?: boolean
  validationState?: ValidationState
  id?: string
  className?: string
  'aria-label'?: string
}

export function Switch({
  label,
  helperText,
  name,
  size = 'md',
  variant = 'primary',
  disabled,
  required,
  validationState,
  className,
  onCheckedChange,
  ...props
}: SwitchProps) {
  return (
    <ChoiceField
      label={label}
      helperText={helperText}
      validationState={validationState}
      required={required}
      disabled={disabled}
      name={name}
      className={cn(styles[size], className)}
    >
      <BaseSwitch.Root
        {...props}
        required={required}
        onCheckedChange={onCheckedChange && ((next) => onCheckedChange(next))}
        className={cn(choiceStyles.control, styles.track, styles[variant])}
      >
        <BaseSwitch.Thumb className={styles.thumb} />
      </BaseSwitch.Root>
    </ChoiceField>
  )
}

/* Sizes are set on the field so the helper text can indent by the track's
   width. Doubled classes outrank ChoiceField's default, whichever
   stylesheet loads first. Track heights are 16/20/24px; widths are one
   and three quarter heights, so the thumb travels most of a thumb-width. */
.sm.sm {
  --choice-control: calc(var(--space-6) + var(--space-1));
  --choice-control-block: var(--space-4);
}
.md.md {
  --choice-control: calc(var(--space-8) + var(--space-1));
  --choice-control-block: calc(var(--space-4) + var(--space-1));
}
.lg.lg {
  --choice-control: calc(var(--space-10) + var(--space-1));
  --choice-control-block: var(--space-6);
}

/* Off: a --control-border track (3:1 on the page, so the control is
   visible at all) with a page-coloured thumb. On: the variant's solid and
   its label colour, which is measured at 4.5:1 against it. */
.track {
  --switch-on: var(--primary);
  --switch-on-thumb: var(--primary-foreground);
  display: inline-flex;
  align-items: center;
  inline-size: var(--choice-control);
  block-size: var(--choice-control-block);
  /* 2px between track edge and thumb at every size. */
  padding: 2px;
  border-radius: 9999px;
  background: var(--control-border);
  cursor: var(--cursor-button);
  transition: background-color 150ms;
}

.accent {
  --switch-on: var(--foreground);
  --switch-on-thumb: var(--background);
}
.destructive {
  --switch-on: var(--destructive);
  --switch-on-thumb: var(--destructive-foreground);
}

.track[data-checked] {
  background: var(--switch-on);
}

.track[data-readonly] {
  cursor: default;
}

/* Invalid: a danger-coloured edge INSIDE the track, so it reads on and off
   alike and leaves the band outside the track to the focus ring — an
   outside ring here would sit exactly where focus draws and hide it. The
   helper text says what is wrong. */
.track[data-invalid] {
  box-shadow: inset 0 0 0 2px var(--danger-text);
}

.thumb {
  block-size: calc(var(--choice-control-block) - 4px);
  aspect-ratio: 1;
  border-radius: 9999px;
  background: var(--background);
  transition:
    translate 150ms,
    background-color 150ms;
}

.thumb[data-checked] {
  /* The full travel: track width minus the thumb and both 2px gaps. */
  translate: calc(var(--choice-control) - var(--choice-control-block)) 0;
  background: var(--switch-on-thumb);
}

/* translate is physical; in a right-to-left page the thumb starts on the
   right and travels left. Not :dir(rtl): the build lowers it to a list of
   :lang()s, which misses a dir="rtl" page in any other language. */
:global([dir='rtl']) .thumb[data-checked] {
  translate: calc(var(--choice-control-block) - var(--choice-control)) 0;
}
:global([dir='rtl'] [dir='ltr']) .thumb[data-checked] {
  translate: calc(var(--choice-control) - var(--choice-control-block)) 0;
}

@media (prefers-reduced-motion: reduce) {
  .track,
  .thumb {
    transition: none;
  }
}
